function canReach(arr, start) {
    const q = [start];
    for (const i of q) {
        if (arr[i] === 0) {
            return true;
        }
        if (arr[i] === -1 || arr[i] === undefined) {
            continue;
        }
        q.push(i + arr[i], i - arr[i]);
        arr[i] = -1;
    }
    return false;
}

